H.background();
const speed = P.speed; // magnet oscillation speed scale (m/s)
const pole = P.pole;   // +1 = N pole facing coil, -1 = S pole facing coil
H.text("Lenz's law: induced current opposes the CHANGE in flux", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Approaching N pole -> coil presents its N face and repels the magnet", 24, 52, { color: H.colors.sub, size: 13 });
const coilX = H.W * 0.62, cy = H.H / 2 + 10;
const coilH = 150;
for (let k = 0; k < 7; k++) {
  const y = cy - coilH / 2 + coilH * k / 6;
  H.circle(coilX, y, 46, { stroke: H.colors.grid, width: 1 });
}
H.rect(coilX - 50, cy - coilH / 2 - 10, 100, coilH + 20, { stroke: H.colors.violet, width: 2, radius: 8 });
H.text("coil", coilX - 14, cy - coilH / 2 - 18, { color: H.colors.violet, size: 12 });
// magnet oscillates toward/away so it stays in frame; its instantaneous velocity drives the physics
const w = 0.4 + Math.abs(speed) * 0.25;
const amp = 150;
const mx = (coilX - 250) + amp * (1 + Math.sin(t * w)) / 2;
const vinst = amp * w * Math.cos(t * w) / 2;   // +x = toward coil
const approaching = vinst > 0;
const mw = 90, mh = 46;
const nFacingCoil = pole >= 0;                  // N pole on the coil (right) side?
H.rect(mx - mw / 2, cy - mh / 2, mw / 2, mh, { fill: nFacingCoil ? H.colors.warn : H.colors.accent });
H.rect(mx, cy - mh / 2, mw / 2, mh, { fill: nFacingCoil ? H.colors.accent : H.colors.warn });
H.text(nFacingCoil ? "S" : "N", mx - mw / 4, cy, { color: H.colors.ink, size: 14, align: "center", baseline: "middle", weight: 700 });
H.text(nFacingCoil ? "N" : "S", mx + mw / 4, cy, { color: H.colors.ink, size: 14, align: "center", baseline: "middle", weight: 700 });
H.arrow(mx, cy - mh / 2 - 16, mx + (vinst >= 0 ? 36 : -36), cy - mh / 2 - 16, { color: H.colors.yellow, width: 2 });
H.text("v", mx + (vinst >= 0 ? 40 : -50), cy - mh / 2 - 16, { color: H.colors.yellow, size: 12, baseline: "middle" });
// Sign of dPhi/dt: facing-pole base sign s, times +1 if approaching (|flux| growing) else -1.
const s = nFacingCoil ? 1 : -1;
const dPhi = s * (approaching ? 1 : -1);
// Coil opposes: near face repels an approaching magnet (same pole), attracts a receding one.
const nearFaceN = approaching ? nFacingCoil : !nFacingCoil;
H.text("coil near face: " + (nearFaceN ? "N" : "S"), coilX - 36, cy + coilH / 2 + 24, { color: nearFaceN ? H.colors.warn : H.colors.accent, size: 13 });
// induced current dot circulating; direction flips with sign of dPhi/dt, speed ~ |induced I|
const Iind = Math.min(4, Math.abs(speed) * 0.9 + 0.3);
const ca = (dPhi > 0 ? 1 : -1) * t * Iind;
H.circle(coilX + 46 * Math.cos(ca), cy + 46 * Math.sin(ca), 7, { fill: H.colors.good });
// Lenz force on magnet: pushes it away when approaching, pulls it back when receding
const fdir = approaching ? -1 : 1;
H.arrow(mx + mw / 2 + 6, cy, mx + mw / 2 + 6 + fdir * 34, cy, { color: H.colors.accent2, width: 2 });
H.text("F_coil", mx + mw / 2 + 10, cy - 14, { color: H.colors.accent2, size: 11 });
const motion = approaching ? "approaching -> flux rising -> coil REPELS" : "receding -> flux falling -> coil ATTRACTS";
H.text(motion + "   (|I_induced| ~ " + Iind.toFixed(1) + ", speed=" + speed.toFixed(1) + " m/s)", 24, 76, { color: H.colors.sub, size: 13 });
